/**
 * Event Service Client for Expo/React Native
 * Fetches events from local API server (server-side Ticketmaster calls)
 * This avoids exposing API keys in the client
 */

// Local API server URL - MUST use host LAN IP for physical iPhone
// The server runs on the host machine and Expo Go on iPhone needs the host IP
const API_BASE_URL = 'http://192.168.68.101:8080';

const TIMEOUT = 15000;

/**
 * Fetch events from local API server
 * The server handles Ticketmaster API calls with the stored API key
 */
async function fetchFromAPI(endpoint = '/events') {
  try {
    const response = await fetch(`${API_BASE_URL}${endpoint}`, {
      method: 'GET',
      headers: {
        'Accept': 'application/json',
        'Content-Type': 'application/json',
      },
    });

    if (!response.ok) {
      console.warn(`[EventService] API error: ${response.status}`);
      return null;
    }

    return await response.json();
  } catch (error) {
    console.warn(`[EventService] Network error: ${error.message}`);
    return null;
  }
}

/**
 * Fetch Ticketmaster events from local API server
 */
export async function fetchTicketmasterEventsViaServer() {
  const data = await fetchFromAPI('/events');

  if (!data || !data.ticketmaster) {
    console.warn('[EventService] No data from API server');
    return [];
  }

  if (data.ticketmaster.error) {
    console.warn(`[EventService] Ticketmaster error: ${data.ticketmaster.error}`);
    return [];
  }

  return data.ticketmaster.events || [];
}

/**
 * Fetch all events (Ticketmaster + other sources)
 */
export async function fetchAllEventsViaServer() {
  const data = await fetchFromAPI('/events');

  if (!data) {
    return { events: [], sources: [], error: 'API unavailable' };
  }

  const allEvents = [];

  // Add Ticketmaster events (source is already set by API server)
  if (data.ticketmaster?.events) {
    allEvents.push(...data.ticketmaster.events);
  }

  // Add Kulturhuset events
  if (data.otherSources?.sources?.kulturhuset) {
    allEvents.push(...data.otherSources.sources.kulturhuset);
  }

  // Add Malmö Live events (source is normalized by API server)
  if (data.otherSources?.sources?.malmolive) {
    allEvents.push(...data.otherSources.sources.malmolive);
  }

  // Return available sources from API server for dropdown
  // The API server provides sources based on what's actually available
  const sources = data.sources || [];

  return {
    events: allEvents,
    sources: sources,
    count: allEvents.length,
    ticketmasterCount: data.ticketmaster?.count || 0,
  };
}

/**
 * Health check for API server
 */
export async function checkAPIHealth() {
  const data = await fetchFromAPI('/health');

  if (!data) {
    return { connected: false, error: 'Cannot reach API server' };
  }

  return {
    connected: true,
    status: data.status,
    ticketmasterKey: data.ticketmasterKey,
  };
}

// Export for use in App.js
export const fetchEvents = fetchAllEventsViaServer;
export { API_BASE_URL };

