 * Fetch all events (Ticketmaster + other sources)
 */
export async function fetchAllEventsViaServer() {
  const data = await fetchFromAPI('/events');

  if (!data) {
    return { events: [], sources: [], error: 'API unavailable' };
  }

  const allEvents = [];

  // Add Ticketmaster events (source is already set by API server)
  if (data.ticketmaster?.events) {
    allEvents.push(...data.ticketmaster.events);
  }

  // Add Kulturhuset events
  if (data.otherSources?.sources?.kulturhuset) {
    allEvents.push(...data.otherSources.sources.kulturhuset);
  }

  // Add Malmö Live events (source is normalized by API server)
  if (data.otherSources?.sources?.malmolive) {
