/**
 * Fetch events with automatic fallback
 * Tries Supabase first, then falls back to direct API
 */
export async function fetchEventsSmart() {
  // Try Supabase first (normalized data)
  const supabaseData = await fetchFromSupabase();

  if (supabaseData && supabaseData.events.length > 0) {
    console.log('[EventService] Using Supabase (normalized) events');
